1	/* ============================ Lái xe: dữ liệu mạng đường ============================
2	   Sinh danh sách ô mặt đường DrPad[] (spec §4) từ CONFIG.drive.roads và biên dạng cao độ của bốn cầu + hầm. Không import three.
3	   - Mỗi chiều xe của mỗi tuyến là một dãy ô (hậu tố .N / .S cho tuyến dọc X, .W / .E cho tuyến dọc Z); dải giữa không thuộc ô nào nên tự chặn.
4	   - Mỗi nút giao là một ô 'junction' phủ cả hai chiều và dải giữa (chỗ mở dải giữa để rẽ trái, quay đầu); cuối mỗi đường cụt có một ô
5	     'junction' để quay đầu. Ô 'road' / 'slip' / 'junction' chưa có mặt đường thì Task 2 (environment/driveRoads.ts) dựng từ chính các ô này.
6	   - Gầm Cầu Rồng đóng (người dùng chọn 2026-11-12): đường ven sông không có ô giữa hai nhánh rẽ; xe đổi phía qua ô nút giao trên trục z = 0 ngay ngoài |x| = 333.
7	   - Đường ven sông chui dưới Trần Thị Lý, Thuận Phước và chạy trên hầm: ô chồng mặt bằng nhưng khác tầng.
8	
9	   Bảng nguồn số (file : hình học đã đọc):
10	   | Tuyến | Mặt cắt mỗi chiều (|z − tim| hoặc |x − tim|) | Dọc tuyến | Nguồn |
11	   | Trục Cầu Rồng z = 0 | 3..16,25 (dải giữa 6, 3 làn × 3,75 + lề 2); trên cầu tới gờ chắn xe 15,9 | x −1900..1480, cầu |x| ≤ 333 (deckY) | streets.ts:15-22; dragon/deck.ts:13-22 |
12	   | Trục Cầu sông Hàn z = −1080 | 1,1..4,45 (1 làn 3,35) | x −1900..1480, cầu |x| ≤ 290 (shRoadY), nhịp quay |x| ≤ 62,35 | song-han/fixedSpans.ts:46-52; config.ts deriveSh |
13	   | Trục Trần Thị Lý z = 1300 | 2,75..14,0 (3 làn × 3,75) | x −1900..1480, cầu x −470..450 (ttlRoadY) | tran-thi-ly/deck.ts:12-20 |
14	   | Trục hầm z = −1700 | 2,1..14,6 (tim ống 8,35, bề rộng 12,5) | x −1900..1480, ống |x| ≤ 697,5 (hrRoadY) | han-tunnel/outdoor.ts:93-96; bore.ts:38-40 |
15	   | Trục Thuận Phước z = −2900 | 0,5..7,5 (dải giữa 1, 2 làn × 3,5) | x −1500..1480, cầu |x| ≤ 1047,5 (tpRoadY) | thuan-phuoc/deck.ts:27-36; profile.ts |
16	   | Đường ven sông |x| = 299 | 1,5..10,5 (hai dải 9 m, dải giữa 3 m) | Tây z −3210..2600, Đông −3660..2600 | streets.ts:25-29; thuan-phuoc/site.ts:31-38 |
17	   Cao độ ô đường bằng phẳng lấy CONFIG.roadY (mặt vẽ ở streets.ts cao hơn 0,02 m, ở site.ts thấp hơn 0,08 m; trong stepMax). */
18	import { CONFIG } from '../../config';
19	import { deckY } from '../../bridges/dragon/profile';
20	import { SH, shRoadY } from '../../bridges/song-han/profile';
21	import { TTL, ttlRoadY } from '../../bridges/tran-thi-ly/profile';
22	import { TP, tpRoadY } from '../../bridges/thuan-phuoc/profile';
23	import { HR, hrRoadY } from '../../bridges/han-tunnel/profile';
24	import type { DrPad } from './net';
25	
26	export const DR_GATE_SWING = 'shSwing';
27	
28	type DrY = DrPad['y'];
29	const R = CONFIG.drive.roads, ROAD = CONFIG.roadY;
30	const flat: DrY = () => ROAD;
31	const LIN = R.median / 2, LOUT = LIN + R.half;                      // 1,5 / 10,5 — mặt cắt đường mới và đường ven sông
32	const AX0 = R.axisX0, AX1 = R.axisX1;
33	
34	/* ----- Cầu Rồng (streets.ts, dragon/deck.ts) ----- */
35	const DR_X = CONFIG.length / 2;                                     // 333 — đầu mặt cầu, deckY(±333) = roadY
36	const DR_IN = CONFIG.median / 2;                                    // 3
37	const DR_OUT = DR_IN + CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder;   // 16,25 — mép ngoài lề xe, trên bờ
38	const DR_CURB = DR_OUT - 0.35;                                      // 15,9 — mặt trong gờ chắn xe trên cầu (dragon/deck.ts:21)
39	/* ----- Cầu sông Hàn (fixedSpans.ts) ----- */
40	const SH_IN = SH.median / 2;                                        // 1,1
41	const SH_OUT = SH.lane + SH.laneWidth / 2;                          // 4,45
42	const SH_X = SH.roadProfile[SH.roadProfile.length - 2][0];          // 290 — mặt cầu về roadY (lan can phần cố định tới đây)
43	/* ----- Trần Thị Lý (tran-thi-ly/deck.ts) ----- */
44	const TTL_IN = TTL.median / 2;                                      // 2,75
45	const TTL_OUT = TTL_IN + TTL.lanesPerDir * TTL.laneWidth;           // 14,0
46	const TTL_W = TTL.roadProfile[1][0], TTL_E = TTL.roadProfile[TTL.roadProfile.length - 2][0];   // −470 / 450 — chân dốc hai đầu (deck.ts xr0 / xr1)
47	/* ----- Hầm (han-tunnel/outdoor.ts, bore.ts) ----- */
48	const HR_W = HR.shoulder * 2 + HR.laneWidth * HR.lanesPerDir;       // 12,5 — bề rộng mặt đường mỗi ống
49	const HR_IN = HR.tubeCenter - HR_W / 2, HR_OUT = HR.tubeCenter + HR_W / 2;   // 2,1 / 14,6
50	/* ----- Thuận Phước (thuan-phuoc/deck.ts) ----- */
51	const TP_IN = TP.median / 2;                                        // 0,5
52	const TP_OUT = TP_IN + 2 * TP.laneWidth;                            // 7,5
53	const TP_END = TP.endX + TP.embankment;                             // 1047,5 — đường đắp về mặt đất
54	
55	/* ===== Mô tả tuyến ===== */
56	interface DrRect { id: string; x0: number; x1: number; z0: number; z1: number }
57	interface DrSpan { id: string; kind: DrPad['kind']; a: number; b: number; y: DrY; out?: number; gate?: string }
58	interface DrLine {
59	  id: string; along: 'x' | 'z'; c: number; lin: number; lout: number;   // tim tuyến (z nếu dọc X, x nếu dọc Z), mép trong / ngoài mỗi chiều tính từ tim
60	  a: number; b: number; y: DrY;                                     // đoạn dọc tuyến, cao độ phần đường thường
61	  spans?: DrSpan[];                                                 // đoạn cầu / hầm: ô riêng mỗi chiều, kind và cao độ riêng
62	  holes?: [number, number][];                                       // đoạn không có ô (gầm Cầu Rồng)
63	}
64	
65	const AXES: DrLine[] = [
66	  { id: 'dragon', along: 'x', c: 0, lin: DR_IN, lout: DR_OUT, a: AX0, b: AX1, y: flat,
67	    spans: [{ id: 'dragon.bridge', kind: 'bridge', a: -DR_X, b: DR_X, y: (x) => deckY(x), out: DR_CURB }] },
68	  { id: 'songHan', along: 'x', c: SH.z, lin: SH_IN, lout: SH_OUT, a: AX0, b: AX1, y: (x) => shRoadY(x),
69	    spans: [
70	      { id: 'songHan.bridgeW', kind: 'bridge', a: -SH_X, b: -SH.fixedStart, y: (x) => shRoadY(x) },
71	      { id: 'songHan.swing', kind: 'bridge', a: -SH.fixedStart, b: SH.fixedStart, y: (x) => shRoadY(x), gate: DR_GATE_SWING },
72	      { id: 'songHan.bridgeE', kind: 'bridge', a: SH.fixedStart, b: SH_X, y: (x) => shRoadY(x) }
73	    ] },
74	  { id: 'ttl', along: 'x', c: TTL.z, lin: TTL_IN, lout: TTL_OUT, a: AX0, b: AX1, y: (x) => ttlRoadY(x),
75	    spans: [{ id: 'ttl.bridge', kind: 'bridge', a: TTL_W, b: TTL_E, y: (x) => ttlRoadY(x) }] },
76	  { id: 'tunnel', along: 'x', c: HR.z, lin: HR_IN, lout: HR_OUT, a: AX0, b: AX1, y: (x) => hrRoadY(x),
77	    spans: [{ id: 'tunnel.tube', kind: 'tunnel', a: -HR.rampHalf, b: HR.rampHalf, y: (x) => hrRoadY(x) }] },   // .N / .S = ống Bắc / ống Nam
78	  { id: 'thuanPhuoc', along: 'x', c: TP.z, lin: TP_IN, lout: TP_OUT, a: R.tpX0, b: AX1, y: (x) => tpRoadY(x),
79	    spans: [{ id: 'thuanPhuoc.bridge', kind: 'bridge', a: -TP_END, b: TP_END, y: (x) => tpRoadY(x) }] }
80	];
81	const SD = R.slipDragon, ST = R.slipTtl;
82	const RIVERS: DrLine[] = [
83	  { id: 'bachDang', along: 'z', c: -R.riverX, lin: LIN, lout: LOUT, a: R.northW, b: R.southZ, y: flat, holes: [[-SD.zIn, SD.zIn]] },
84	  { id: 'tranHungDao', along: 'z', c: R.riverX, lin: LIN, lout: LOUT, a: R.northE, b: R.southZ, y: flat, holes: [[-SD.zIn, SD.zIn]] }
85	];
86	const VERTS: DrLine[] = [
87	  { id: 'west', along: 'z', c: R.westX, lin: LIN, lout: LOUT, a: TP.z - TP_OUT, b: TTL.z + TTL_OUT, y: flat },
88	  { id: 'east', along: 'z', c: R.eastX, lin: LIN, lout: LOUT, a: TP.z - TP_OUT, b: TTL.z + TTL_OUT, y: flat }
89	];
90	const LINKS: DrLine[] = [
91	  { id: 'linkW', along: 'x', c: R.linkWestZ, lin: LIN, lout: LOUT, a: R.westX, b: -R.riverX, y: flat },
92	  { id: 'linkE', along: 'x', c: R.linkEastZ, lin: LIN, lout: LOUT, a: R.riverX, b: R.eastX, y: flat }
93	];
94	
95	/* ===== Nút giao ===== */
96	function drJunctions(): DrRect[] {
97	  const out: DrRect[] = [];
98	  const add = (id: string, x0: number, x1: number, z0: number, z1: number) => out.push({ id, x0, x1, z0, z1 });
99	  for (const A of AXES) {                                           // quay đầu ở hai đầu trục ngang
100	    add(`jct.${A.id}.endW`, A.a, A.a + R.endLen, A.c - A.lout, A.c + A.lout);
101	    add(`jct.${A.id}.endE`, A.b - R.endLen, A.b, A.c - A.lout, A.c + A.lout);
102	  }
103	  for (const V of VERTS) {                                          // đường dọc mới cắt năm trục ngang và đường nối
104	    for (const A of AXES) add(`jct.${V.id}.${A.id}`, V.c - LOUT, V.c + LOUT, A.c - A.lout, A.c + A.lout);
105	    const L = V.id === 'west' ? R.linkWestZ : R.linkEastZ;
106	    add(`jct.${V.id}.link`, V.c - LOUT, V.c + LOUT, L - LOUT, L + LOUT);
107	  }
108	  for (const V of RIVERS) {
109	    const x0 = V.c - LOUT, x1 = V.c + LOUT, L = V.c < 0 ? R.linkWestZ : R.linkEastZ;
110	    add(`jct.${V.id}.endN`, x0, x1, V.a, V.a + R.endLen);
111	    add(`jct.${V.id}.link`, x0, x1, L - LOUT, L + LOUT);
112	    add(`jct.${V.id}.songHan`, x0, x1, SH.z - SH_OUT, SH.z + SH_OUT);   // giao cùng cao độ duy nhất có sẵn
113	    add(`jct.${V.id}.dragon.N`, x0, x1, -SD.zOut, -SD.zIn);
114	    add(`jct.${V.id}.dragon.S`, x0, x1, SD.zIn, SD.zOut);
115	    add(`jct.${V.id}.ttl.N`, x0, x1, TTL.z - ST.zOut, TTL.z - ST.zIn);
116	    add(`jct.${V.id}.ttl.S`, x0, x1, TTL.z + ST.zIn, TTL.z + ST.zOut);
117	  }
118	  add('jct.dragon.W', -DR_X - SD.jLen, -DR_X, -SD.zOut, SD.zOut);  // chỗ nhánh rẽ nhập trục, ngay ngoài chân Cầu Rồng (cũng là chỗ đổi phía qua gầm)
119	  add('jct.dragon.E', DR_X, DR_X + SD.jLen, -SD.zOut, SD.zOut);
120	  add('jct.ttl.W', TTL_W - ST.jLen, TTL_W, TTL.z - ST.zOut, TTL.z + ST.zOut);
121	  add('jct.ttl.E', TTL_E, TTL_E + ST.jLen, TTL.z - ST.zOut, TTL.z + ST.zOut);
122	  return out;
123	}
124	
125	/* ===== Rải ô dọc một tuyến: cắt bởi nút giao chồng lên dải đường và lỗ; đoạn cầu / hầm thành ô riêng; phần còn lại là ô đường ===== */
126	function drFillLine(L: DrLine, jcts: DrRect[], out: DrPad[]): void {
127	  const X = L.along === 'x';
128	  const sides: [string, number][] = X ? [['N', -1], ['S', 1]] : [['W', -1], ['E', 1]];
129	  const emit = (id: string, kind: DrPad['kind'], a: number, b: number, y: DrY, lout: number, gate?: string) => {
130	    for (const [sfx, s] of sides) {
131	      const c0 = L.c + s * L.lin, c1 = L.c + s * lout, lo = Math.min(c0, c1), hi = Math.max(c0, c1);
132	      const p: DrPad = X ? { id: `${id}.${sfx}`, kind, x0: a, x1: b, z0: lo, z1: hi, y } : { id: `${id}.${sfx}`, kind, x0: lo, x1: hi, z0: a, z1: b, y };
133	      if (gate) p.gate = gate;
134	      out.push(p);
135	    }
136	  };
137	  type Cut = { a: number; b: number; span?: DrSpan };
138	  const cuts: Cut[] = [];
139	  const bc0 = L.c - L.lout, bc1 = L.c + L.lout;                     // dải đường theo mặt cắt ngang
140	  for (const j of jcts) {
141	    const [ja, jb, jc0, jc1] = X ? [j.x0, j.x1, j.z0, j.z1] : [j.z0, j.z1, j.x0, j.x1];
142	    if (Math.min(jb, L.b) - Math.max(ja, L.a) > 1e-6 && Math.min(jc1, bc1) - Math.max(jc0, bc0) > 1e-6) cuts.push({ a: ja, b: jb });
143	  }
144	  for (const [a, b] of L.holes || []) cuts.push({ a, b });
145	  for (const s of L.spans || []) cuts.push({ a: s.a, b: s.b, span: s });
146	  cuts.sort((p, q) => p.a - q.a);
147	  let cur = L.a, k = 0;
148	  for (const c of cuts) {
149	    if (c.a > cur + 1e-6) emit(`${L.id}.${k++}`, 'road', cur, Math.min(c.a, L.b), L.y, L.lout);
150	    if (c.span) {                                                   // đoạn cầu bị nút giao đè đầu / cuối thì cắt bớt (Cầu sông Hàn |x| 288,5..290)
151	      const a = Math.max(cur, c.a); let b = c.b;
152	      for (const d of cuts) if (d !== c && d.a >= a && d.a < b) b = d.a;
153	      if (b > a + 1e-6) emit(c.span.id, c.span.kind, a, b, c.span.y, c.span.out ?? L.lout, c.span.gate);
154	    }
155	    cur = Math.max(cur, c.b);
156	  }
157	  if (L.b > cur + 1e-6) emit(`${L.id}.${k++}`, 'road', cur, L.b, L.y, L.lout);
158	}
159	
160	/* ===== Danh sách ô ===== */
161	export function drBuildPads(): DrPad[] {
162	  const out: DrPad[] = [], jcts = drJunctions();
163	  for (const j of jcts) out.push({ id: j.id, kind: 'junction', x0: j.x0, x1: j.x1, z0: j.z0, z1: j.z1, y: flat });
164	  for (const L of [...AXES, ...RIVERS, ...VERTS, ...LINKS]) drFillLine(L, jcts, out);
165	  /* nhánh rẽ hai chiều: từ ô nút giao trên trục tới mép ngoài đường ven sông, đi hai bên dốc cầu */
166	  const slip = (id: string, x0: number, x1: number, z0: number, z1: number) => out.push({ id, kind: 'slip', x0, x1, z0, z1, y: flat });
167	  const rOut = R.riverX + LOUT;                                     // 309,5 — mép ngoài đường ven sông phía đất liền
168	  for (const [sx, s] of [['W', -1], ['E', 1]] as [string, number][]) {
169	    const [dx0, dx1] = s < 0 ? [-DR_X, -rOut] : [rOut, DR_X];
170	    slip(`slip.dragon.${sx}.N`, dx0, dx1, -SD.zOut, -SD.zIn);
171	    slip(`slip.dragon.${sx}.S`, dx0, dx1, SD.zIn, SD.zOut);
172	    const [tx0, tx1] = s < 0 ? [TTL_W, -rOut] : [rOut, TTL_E];
173	    slip(`slip.ttl.${sx}.N`, tx0, tx1, TTL.z - ST.zOut, TTL.z - ST.zIn);
174	    slip(`slip.ttl.${sx}.S`, tx0, tx1, TTL.z + ST.zIn, TTL.z + ST.zOut);
175	  }
176	  return out;
177	}
178	
179	/* Chỗ xuất phát slot: trên Cầu Rồng, làn giữa chiều đi Đông (z > 0, yaw = 0), lệch theo x gap × (slot − 2); slot < 0 (lái một mình) dùng giữa */
180	export function drSpawnPose(slot: number): { x: number; z: number; yaw: number } {
181	  const S = CONFIG.drive.spawn, k = slot < 0 ? 2 : slot;
182	  return { x: S.x + S.gap * (k - 2), z: S.lane, yaw: 0 };
183	}
184

