import * as THREE from 'three';
import { CONFIG } from '../../config';
import { lerp, clamp } from '../../common/math';

/* [config] Cầu Trần Thị Lý: cao độ mặt đường, tiết diện và trục tháp nghiêng. Thông số ở CONFIG.tranThiLy */
export const TTL = CONFIG.tranThiLy;
export const ttlPattern = { value: 2 };   // pattern LED: 0 tĩnh, 1 chuyển màu chậm, 2 sóng màu chạy dọc dây

/* Cao độ mặt đường: đường cong Catmull-Rom qua các điểm roadProfile, tra bảng cho nhanh */
let ttlLut: number[][] = null;
export function ttlRoadY(x: number) {
  const P = TTL.roadProfile;
  if (x <= P[0][0] || x >= P[P.length - 1][0]) return CONFIG.roadY;
  if (!ttlLut) {
    const c = new THREE.CatmullRomCurve3(P.map(([a, b]) => new THREE.Vector3(a, b, 0)), false, 'centripetal');
    ttlLut = c.getPoints(4000).map((v) => [v.x, v.y]).sort((a, b) => a[0] - b[0]);
  }
  let lo = 0, hi = ttlLut.length - 1;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (ttlLut[mid][0] < x) lo = mid; else hi = mid; }
  const [x0, y0] = ttlLut[lo], [x1, y1] = ttlLut[hi];
  return Math.max(CONFIG.roadY, lerp(y0, y1, (x - x0) / Math.max(1e-6, x1 - x0)));
}
/* Tiết diện tháp theo t (0 = chân, 1 = đỉnh), trong hệ tọa độ trục tháp: mép sau (phía Tây) gần thẳng,
   mép trước cong căng như cánh buồm. Ước lượng — sẽ chỉnh theo ảnh tham khảo. */
export function ttlPylonSection(t: number) {
  const Lx = TTL.pylonLen[1] + (TTL.pylonLen[0] - TTL.pylonLen[1]) * Math.pow(1 - t, 1.4) + 2.4 * Math.sin(Math.PI * t) * (1 - t);
  const Wz = lerp(TTL.pylonWid[0], TTL.pylonWid[1], t);
  const back = -4 + 2 * t;
  return { Lx, Wz, back, front: back + Lx };
}
/* Ma trận dựng tháp: dựng thẳng rồi xoay quanh trục ngang (Z) tại chân tháp, nghiêng về phía Tây (−X) */
export const ttlPylonMatrix = new THREE.Matrix4()
  .makeTranslation(TTL.pylonX, TTL.pylonBaseY, 0)
  .multiply(new THREE.Matrix4().makeRotationZ(TTL.lean));
export function ttlPylonPoint(t: number, lx: number, lz: number, out = new THREE.Vector3()) {
  return out.set(lx, t * TTL.axisLen, lz).applyMatrix4(ttlPylonMatrix);
}
/* Cao độ cầu Nguyễn Văn Trỗi cũ (đi bộ) */
export function nvtY(x: number) {
  const ax = Math.abs(x), B = CONFIG.bankX;
  return ax <= B ? TTL.nvtDeckY : lerp(TTL.nvtDeckY, CONFIG.landY + 0.1, clamp((ax - B) / 26, 0, 1));
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { MAT } from '../../core/materials';
import { prepColored, extrudeAlongX, roadStrip, bentBox, shadowed } from '../../common/geometry';
import { addDeckEdges, addJoints, addLampPosts } from '../../common/deck';
import { flatY } from '../dragon/profile';
import { TTL, ttlRoadY } from './profile';
import type { TranThiLyBridge } from './TranThiLyBridge';
import { drCutAlongX } from '../../environment/driveRoadGeo';

/* [deck] dầm hộp 34,5 m, 6 làn, dải phân cách 5,5 m, lề, lan can, đèn, dải LED */
export function ttlBuildDeck(bridge: TranThiLyBridge) {
  const M = bridge.mats, hw = TTL.hw, W = TTL.westEnd, E = TTL.eastEnd, xr0 = -470, xr1 = 450;
  // Dầm hộp BTCT: bản mặt rộng 34,5 m, cánh hẫng mỏng dần hai bên, hộp giữa sườn vát (tiết diện ước lượng)
  const sec = [[-hw, 0], [hw, 0], [hw, -0.35], [11, -0.75], [9, -TTL.girderDepth], [-9, -TTL.girderDepth], [-11, -0.75], [-hw, -0.35]];
  bridge.concreteParts.push(prepColored(extrudeAlongX(sec, W, E, 320, ttlRoadY)));
  // Mặt đường 6 làn (3 làn mỗi chiều) + đường nối trên bờ hai đầu
  const car = TTL.lanesPerDir * TTL.laneWidth, zc = TTL.median / 2 + car / 2;
  const road = new THREE.Mesh(mergeGeometries([
    roadStrip(-1900, 1480, car, zc, 0.03, 1000, ttlRoadY),
    roadStrip(-1900, 1480, car, -zc, 0.03, 1000, ttlRoadY, true)
  ]), M.road);
  road.receiveShadow = true; bridge.group.add(road); bridge.noReflect.push(road); bridge.farHide.push(road);
  // Dải phân cách giữa 5,5 m (mang tháp và neo dây trước) + phân cách trên bờ
  bridge.concreteParts.push(prepColored(bentBox(xr1 - xr0, 0.35, TTL.median, (xr0 + xr1) / 2, 0.17, 0, 500, ttlRoadY), () => 0.88));
  const med = [bentBox(xr1 - xr0, 0.06, TTL.median - 0.8, (xr0 + xr1) / 2, 0.37, 0, 500, ttlRoadY)];
  for (const [a, b] of [[-1900, xr0], [xr1, 1480]]) med.push(...drCutAlongX(a, b, TTL.z, TTL.median / 2, 4, (len, xc, n) => bentBox(len, 0.3, TTL.median, xc, 0.15, 0, n, flatY)));   // mở tại nút giao chế độ lái (D-034)
  const mm = shadowed(new THREE.Mesh(mergeGeometries(med), MAT.grass), false, true); bridge.group.add(mm); bridge.noReflect.push(mm); bridge.farHide.push(mm);
  // Lề, gờ, lan can, khe co giãn modular, cột đèn trên dải phân cách (hệ dùng chung common/)
  addDeckEdges(bridge, { x0: xr0, x1: xr1, segs: 500, profile: ttlRoadY, hw, sidewalk: TTL.sidewalk });
  addJoints(bridge, { xs: [W, TTL.pylonX - 120, TTL.mainEnd, E], profile: ttlRoadY, width: TTL.deckWidth - 0.6, mat: M.joint });
  const xs = [];
  for (let x = xr0 + 15; x <= xr1 - 15; x += TTL.lampSpacing) if (Math.abs(x - TTL.pylonX) > 18) xs.push(x);
  addLampPosts(bridge, { xs, profile: ttlRoadY, rows: [{ z: -2.0, s: 1 }, { z: 2.0, s: -1 }] });
  // Dải LED mặt cầu: mép ngoài dầm và mép dải phân cách
  const strips = [];
  for (const s of [-1, 1]) {
    strips.push(bentBox(E - W, 0.14, 0.08, (W + E) / 2, -0.22, s * (hw + 0.04), 400, ttlRoadY));
    strips.push(bentBox(xr1 - xr0, 0.06, 0.06, (xr0 + xr1) / 2, 0.37, s * (TTL.median / 2 - 0.03), 500, ttlRoadY));
  }
  const ls = new THREE.Mesh(mergeGeometries(strips), M.ledStrip); bridge.group.add(ls); bridge.farHide.push(ls);
}
import * as THREE from 'three';
import { prepColored, loftRings, loftOct, boxAt, type LoftRing } from '../../common/geometry';
import { TTL, ttlPylonSection, ttlPylonMatrix, ttlPylonPoint } from './profile';
import type { TranThiLyBridge } from './TranThiLyBridge';

/* [pylon] tháp nghiêng 12° về Tây, khối đế, 2 gối cầu, đèn báo */
export function ttlBuildPylon(bridge: TranThiLyBridge) {
  const M = bridge.mats, rings: LoftRing[] = [];
  for (let i = 0; i < TTL.pylonRings; i++) {
    const t = 0.03 + (1 - 0.03) * i / (TTL.pylonRings - 1);     // bắt đầu hơi cao để phần chân chìm trong khối đế
    const s = ttlPylonSection(t);
    rings.push({ sx: s.Lx, sz: s.Wz, cx: s.back + s.Lx / 2, cz: 0, y: t * TTL.axisLen, ch: Math.min(0.7, 0.14 * Math.min(s.Lx, s.Wz)) });
  }
  const g = loftRings(rings); g.applyMatrix4(ttlPylonMatrix); g.computeVertexNormals();
  const pylon = new THREE.Mesh(g, M.pylon); pylon.name = 'ttl-pylon'; pylon.castShadow = pylon.receiveShadow = true;
  bridge.group.add(pylon);
  // khối đế nằm ngang trên 2 gối cầu, bệ móng trong sông
  const X = TTL.pylonX;
  bridge.concreteParts.push(prepColored(loftOct([16, 7], [14.5, 6.4], TTL.pylonBaseY, 6.6, [X + 2, 0], [X + 1.4, 0], 0.6)));
  bridge.concreteParts.push(prepColored(boxAt(30, 6.5, 28, X + 2, -2.75, 0, 8)));
  // 2 gối cầu cầu khổng lồ (~250.000 kN mỗi gối): đế thép + chỏm cầu
  for (const bx of [X - 1.5, X + 5.5]) {
    bridge.steelParts.push(new THREE.CylinderGeometry(TTL.bearingR, TTL.bearingR + 0.25, 0.5, 24).translate(bx, 0.75, 0).toNonIndexed());
    bridge.steelParts.push(new THREE.SphereGeometry(TTL.bearingR * 0.9, 20, 8, 0, Math.PI * 2, 0, Math.PI / 2).scale(1, 0.38, 1).translate(bx, 1.0, 0).toNonIndexed());
  }
  // đèn báo hàng không trên đỉnh
  const top = ttlPylonSection(1), beacons = new THREE.InstancedMesh(new THREE.SphereGeometry(0.55, 10, 8), M.beacon, 2), m = new THREE.Matrix4(), p = new THREE.Vector3();
  [-1, 1].forEach((sz, i) => { ttlPylonPoint(1, top.back + top.Lx / 2, sz * 0.9, p); beacons.setMatrixAt(i, m.makeTranslation(p.x, p.y + 0.8, p.z)); });
  bridge.group.add(beacons);
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { lerp } from '../../common/math';
import { prepColored, segmentMatrix } from '../../common/geometry';
import { TTL, ttlRoadY, ttlPylonSection, ttlPylonPoint } from './profile';
import type { TranThiLyBridge } from './TranThiLyBridge';

/* [stayCables] mặt trước rẻ quạt + 2 mặt sau rẻ quạt xoắn, ống HDPE
   Trả về danh sách dây: { a: điểm neo tháp, b: điểm neo dầm, plane: 0 trước / −1, +1 sau } */
export function ttlStayList() {
  const out: { a: THREE.Vector3; b: THREE.Vector3; plane: number; k: number }[] = [], [tLo, tHi] = TTL.anchorT;
  // Mặt trước: một mặt phẳng ở tim cầu, nửa rẻ quạt — neo cao nhất trên tháp ↔ neo xa nhất trên dầm
  for (let i = 0; i < TTL.staysFront; i++) {
    const k = i / (TTL.staysFront - 1), t = lerp(tHi, tLo, k), s = ttlPylonSection(t);
    const x = TTL.pylonX + lerp(TTL.frontDeck[1], TTL.frontDeck[0], k);
    out.push({ a: ttlPylonPoint(t, s.front - 0.3, 0), b: new THREE.Vector3(x, ttlRoadY(x) + 0.9, 0), plane: 0, k });
  }
  // Hai mặt sau: rẻ quạt xoắn — neo cao nhất trên tháp ↔ neo GẦN tháp nhất ở mép ngoài dầm,
  // neo thấp nhất ↔ xa nhất; các dây giao chéo nhau, bề mặt gần một paraboloid hyperbolic
  for (const sz of [-1, 1]) for (let i = 0; i < TTL.staysBack; i++) {
    const k = i / (TTL.staysBack - 1), t = lerp(tHi, tLo, k), s = ttlPylonSection(t);
    const x = TTL.pylonX - lerp(TTL.backDeck[0], TTL.backDeck[1], k);
    out.push({ a: ttlPylonPoint(t, s.back + 0.3, sz * (s.Wz / 2 - 0.35)), b: new THREE.Vector3(x, ttlRoadY(x) - 0.3, sz * TTL.backDeckZ), plane: sz, k });
  }
  return out;
}
export function ttlBuildStays(bridge: TranThiLyBridge) {
  const M = bridge.mats, list = ttlStayList(), m = new THREE.Matrix4(), cyl = new THREE.CylinderGeometry(1, 1, 1, 8);
  const stays = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 8, CONFIG.weather.wind.cableSegs), M.stay, list.length);   // nhiều đoạn dọc để shader lắc uốn cong được dây
  const hdpe = new THREE.InstancedMesh(cyl, M.hdpe, list.length);
  const towerBox = new THREE.InstancedMesh(new THREE.BoxGeometry(1.3, 0.9, 1.3), M.pylon, list.length);
  const deckBox = new THREE.InstancedMesh(prepColored(new THREE.BoxGeometry(1.1, 0.9, 1.1)), M.concrete, list.length);
  const dir = new THREE.Vector3();
  list.forEach(({ a, b }, i) => {
    stays.setMatrixAt(i, segmentMatrix(a, b, TTL.stayR, m));
    dir.subVectors(a, b).normalize();
    hdpe.setMatrixAt(i, segmentMatrix(b, b.clone().addScaledVector(dir, TTL.hdpeLen), TTL.hdpeR, m));
    towerBox.setMatrixAt(i, m.makeTranslation(a.x, a.y, a.z));
    deckBox.setMatrixAt(i, m.makeTranslation(b.x, b.y - 0.3, b.z));
  });
  stays.castShadow = true;
  bridge.group.add(stays);
  bridge.details.add(hdpe, towerBox, deckBox);
  bridge.stats.stays = list.length;
}
import { CONFIG } from '../../config';
import { prepColored, loftOct, boxAt, fillBlock } from '../../common/geometry';
import { TTL, ttlRoadY } from './profile';
import type { TranThiLyBridge } from './TranThiLyBridge';

/* [approaches] trụ thân rộng, mố, đường đắp */
export function ttlBuildApproaches(bridge: TranThiLyBridge) {
  const W = TTL.westEnd, E = TTL.eastEnd, B = CONFIG.bankX;
  // Trụ thân rộng: trong sông có bệ móng (vệt nước bám qua shader 'wet'); trên bờ đặt trên dải phân cách đường ven sông.
  // Trụ là hình tĩnh nên gộp chung vào khối bê tông (1 draw call) thay vì InstancedMesh.
  TTL.piers.forEach((x) => {
    const inRiver = Math.abs(x) < B, y0 = inRiver ? -3 : CONFIG.landY - 1, top = ttlRoadY(x) - TTL.girderDepth;
    bridge.concreteParts.push(prepColored(loftOct([2.6, 19], [2.6, 19], y0, top, [x, 0], [x, 0], 0.5)));
    if (inRiver) bridge.concreteParts.push(prepColored(boxAt(7, 6.6, 25, x, -2.7, 0, 4)));
  });
  // mố + tường chắn đường đắp hai đầu
  for (const [x, a, b] of [[W, -470, W], [E, E, 450]]) {
    bridge.concreteParts.push(prepColored(boxAt(6, ttlRoadY(x) - CONFIG.landY + 1, TTL.deckWidth + 1, x, (ttlRoadY(x) + CONFIG.landY - 1) / 2 - 0.3, 0)));
    bridge.concreteParts.push(prepColored(fillBlock(a, b, TTL.deckWidth, 0, CONFIG.landY - 0.5, (xx) => ttlRoadY(xx) - 0.05, 40), () => 0.82));
  }
}
import * as THREE from 'three';
import { BridgeBase, blinkBeacon } from '../../common/BridgeBase';
import { stepTraffic, type Traffic } from '../../common/traffic';
import { stepBoats, type Boats } from '../../common/boats';
import { stepPeople, type People } from '../../common/people';
import { PATHS } from '../../environment/traffic';
import { TTL, ttlRoadY, ttlPattern } from './profile';
import { ttlMaterials, type TtlMaterials } from './materials';
import { ttlBuildPylon } from './pylon';
import { ttlBuildStays } from './stays';
import { ttlBuildDeck } from './deck';
import { ttlBuildApproaches } from './approaches';
import { ttlBuildNvt } from './nvt';
import { ttlBuildLife } from './life';

/* ======================================================================
   CẦU TRẦN THỊ LÝ — cầu dây văng BTCT một tháp nghiêng, hệ dây 3 mặt phẳng ("cánh buồm căng gió")
   Phía Nam (thượng lưu, +Z) Cầu Rồng ~1,3 km, chạy Tây – Đông.
   Gốc tọa độ cục bộ: tim cầu (x = 0 ở tim sông), group dời tới z = 1300.
   ====================================================================== */
export class TranThiLyBridge extends BridgeBase<TtlMaterials> {
  declare traffic: Traffic;
  declare boats: Boats;
  declare people: People;
  declare nvt: THREE.Group;
  peopleOn = true;

  constructor() {
