import { CONFIG } from '../../config';
import { lerp, clamp } from '../../common/math';

/* [config] Cầu Thuận Phước: thông số ở CONFIG.thuanPhuoc; mọi kích thước tính bằng mét.
   Gốc tọa độ cục bộ: tim cầu; group dời tới z = CONFIG.thuanPhuoc.z. */
export const TP = CONFIG.thuanPhuoc;

/* Cao độ mặt đường theo x: vồng parabol trên phần cầu treo, hạ dần qua 12 nhịp dẫn
   (đường cong Hermite liền dốc, dốc ≤ ~4%), rồi đường đắp về mặt đất. */
export function tpRoadY(x: number) {
  const ax = Math.abs(x), A = TP.anchorX, E = TP.endX, R = TP.embankment;
  const pE = CONFIG.roadY + TP.abutmentRise, gE = -TP.abutmentRise / R; // dốc tại mố
  const herm = (t: number, p0: number, m0: number, p1: number, m1: number) => {
    const t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * p0 + (t3 - 2 * t2 + t) * m0 + (-2 * t3 + 3 * t2) * p1 + (t3 - t2) * m1;
  };
  if (ax <= A) return TP.roadCenterY - (TP.roadCenterY - TP.roadAnchorY) * (ax / A) ** 2;
  if (ax <= E) {
    const L = E - A, m0 = -2 * (TP.roadCenterY - TP.roadAnchorY) / A * L;
    return herm((ax - A) / L, TP.roadAnchorY, m0, pE, gE * L);
  }
  if (ax <= E + R) return herm((ax - E) / R, pE, gE * R, CONFIG.roadY, 0);
  return CONFIG.roadY;
}
/* Cao độ tim cáp chủ: parabol y = y_top − 4f·u(1 − u) */
export function tpCableY(x: number) {
  const ax = Math.abs(x);
  if (ax <= TP.towerX) { const u = (x + TP.towerX) / TP.mainSpan; return TP.saddleY - 4 * TP.sag * u * (1 - u); }
  const t = clamp((ax - TP.towerX) / (TP.cableAnchorX - TP.towerX), 0, 1);
  return lerp(TP.saddleY, TP.anchorCableY, t) - 4 * TP.sideSag * t * (1 - t);
}
/* Vị trí hanger theo x (một mặt phẳng cáp) */
export function tpHangerStations() {
  const out: { x: number; special: boolean }[] = [], nM = TP.hangersMain, dM = TP.mainSpan / (nM + 1), dS = TP.sideSpan / (TP.hangersSide + 1);
  for (let i = 0; i < nM; i++) out.push({ x: -TP.towerX + (i + 1) * dM, special: i < 2 || i >= nM - 2 || i === (nM - 1) / 2 });
  for (const s of [-1, 1]) for (let i = 0; i < TP.hangersSide; i++) {
    out.push({ x: s * (TP.towerX + (i + 1) * dS), special: i === 0 || i === TP.hangersSide - 1 });
  }
  return out;
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { extrudeAlongX, roadStrip, bentBox, prepColored } from '../../common/geometry';
import { addDeckEdges, addJoints, addLampPosts } from '../../common/deck';
import { flatY } from '../dragon/profile';
import { TP, tpRoadY } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';
import { drCutAlongX } from '../../environment/driveRoadGeo';

/* [deck] dầm hộp thép khí động, mặt đường 4 làn, dải phân cách, lề, lan can, cột đèn */
export function tpBuildDeck(bridge: ThuanPhuocBridge) {
  const M = bridge.mats, A = TP.anchorX, E = TP.endX, R = TP.embankment, hw = TP.deckWidth / 2;
  // Dầm hộp thép khí động: mặt trên phẳng, mũi vát hai bên, đáy phẳng (tiết diện ước lượng)
  const tip = TP.girderTip, d = TP.girderDepth;
  const girder = extrudeAlongX([[-hw, 0], [hw, 0], [tip, -0.9], [8.0, -d], [-8.0, -d], [-tip, -0.9]], -A, A, 260, tpRoadY);
  const gm = new THREE.Mesh(girder, M.steel); gm.name = 'tp-girder'; gm.castShadow = gm.receiveShadow = true;
  bridge.group.add(gm);
  // 69 đốt dầm: gân nối đốt ở đáy (chi tiết nhỏ)
  const seg = new THREE.InstancedMesh(new THREE.BoxGeometry(0.3, 0.07, 15.6), M.joint, TP.girderSegments - 1);
  const m = new THREE.Matrix4();
  for (let i = 1; i < TP.girderSegments; i++) {
    const x = -A + i * (2 * A / TP.girderSegments);
    seg.setMatrixAt(i - 1, m.makeTranslation(x, tpRoadY(x) - d - 0.03, 0));
  }
  bridge.details.add(seg);

  // Mặt đường 4 làn + đoạn nối trên bờ (Nguyễn Tất Thành phía Tây, Hoàng Sa – Trường Sa phía Đông)
  const car = 2 * TP.laneWidth, zc = TP.median / 2 + car / 2, x0 = -1500, x1 = 1480;
  const road = mergeGeometries([
    roadStrip(x0, x1, car, zc, 0.03, 900, tpRoadY),
    roadStrip(x0, x1, car, -zc, 0.03, 900, tpRoadY, true)
  ]);
  const rm = new THREE.Mesh(road, M.road); rm.receiveShadow = true; bridge.group.add(rm); bridge.noReflect.push(rm);

  // Dải phân cách (riêng cầu này); lề, gờ, lan can, khe co giãn, cột đèn dùng chung [common]
  const conc = [bentBox(2 * (E + R), 0.45, TP.median, 0, 0.22, 0, 700, tpRoadY)];
  for (const [xa, xb] of [[x0, -E - R], [E + R, x1]]) conc.push(...drCutAlongX(xa, xb, TP.z, TP.median / 2, 4, (len, xc, n) => bentBox(len, 0.3, TP.median, xc, 0.15, 0, n, flatY))); // phân cách trên bờ, mở tại nút giao chế độ lái (D-034)
  bridge.concreteParts.push(...conc.map((g) => prepColored(g, () => 0.9)));
  addDeckEdges(bridge, { x0: -E - R, x1: E + R, segs: 700, profile: tpRoadY, hw, sidewalk: TP.sidewalk });
  addJoints(bridge, { xs: [-E, -A, -TP.towerX, TP.towerX, A, E], profile: tpRoadY, width: TP.deckWidth - 0.6, mat: M.joint });
  const xs = []; for (let x = -E + 15; x <= E - 15; x += TP.lampSpacing) xs.push(x);
  const zl = hw - TP.sidewalk + 0.45;
  addLampPosts(bridge, { xs, profile: tpRoadY, rows: [{ z: -zl, s: -1 }, { z: zl, s: 1 }] });
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { lerp } from '../../common/math';
import { prepColored, wetLineColor, loftOct, boxAt } from '../../common/geometry';
import { TP, tpRoadY } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [towers] tháp BTCT chữ H, yên ngựa, gối cầu, đèn báo hàng không */
export function tpBuildTowers(bridge: ThuanPhuocBridge) {
  const M = bridge.mats, towerParts = [], concrete = [], steel = [];
  const [b0x, b0z] = TP.legBase, [b1x, b1z] = TP.legTop;
  for (const sx of [-1, 1]) {
    const X = sx * TP.towerX;
    concrete.push(prepColored(boxAt(26, TP.pileCapTop + 6, 40, X, (TP.pileCapTop - 6) / 2, 0, 12), wetLineColor)); // bệ cọc
    for (const sz of [-1, 1]) {
      // bệ trụ dưới mỗi cột
      towerParts.push(prepColored(loftOct([b0x + 3.2, b0z + 3.0], [b0x + 2.2, b0z + 2.2], TP.pileCapTop, TP.plinthTop,
        [X, sz * (TP.legZBase + 0.2)], [X, sz * TP.legZBase], TP.chamfer * 1.6), wetLineColor));
      // cột tháp thon dần, nghiêng nhẹ vào trong
      towerParts.push(prepColored(loftOct([b0x, b0z], [b1x, b1z], TP.plinthTop, TP.towerTop,
        [X, sz * TP.legZBase], [X, sz * TP.legZTop], TP.chamfer)));
      // yên ngựa: hộp đế + nắp cong che cáp
      steel.push(boxAt(4.4, 0.8, 2.8, X, TP.towerTop + 0.4, sz * TP.cablePlaneZ));
      const cap = new THREE.CylinderGeometry(1.4, 1.4, 4.4, 16, 1, false, -Math.PI / 2, Math.PI); // nửa trụ, vòm hướng lên
      cap.rotateX(-Math.PI / 2); cap.rotateY(Math.PI / 2);
      cap.translate(X, TP.towerTop + 0.8, sz * TP.cablePlaneZ); steel.push(cap);
    }
    // dầm ngang trên và dưới (z tính tới tim cột ở cao độ tương ứng)
    const zAt = (y: number) => lerp(TP.legZBase, TP.legZTop, (y - TP.plinthTop) / TP.towerHeight);
    const [t0, t1] = TP.topBeam, [l0, l1] = TP.lowBeam;
    towerParts.push(prepColored(loftOct([3.4, 2 * zAt(t0)], [3.4, 2 * zAt(t1)], t0, t1, [X, 0], [X, 0], 0.35)));
    towerParts.push(prepColored(loftOct([4.6, 2 * zAt(l0)], [4.6, 2 * zAt(l1)], l0, l1, [X, 0], [X, 0], 0.35)));
    // gối cầu trên dầm ngang dưới
    for (const z of [-6, 6]) steel.push(boxAt(1.4, tpRoadY(X) - TP.girderDepth - l1, 1.4, X, (l1 + tpRoadY(X) - TP.girderDepth) / 2, z));
  }
  const towers = new THREE.Mesh(mergeGeometries(towerParts), M.tower);
  towers.name = 'tp-towers'; towers.castShadow = towers.receiveShadow = true;
  bridge.group.add(towers);
  bridge.concreteParts.push(...concrete);
  bridge.steelParts.push(...steel.map((g) => (g.index ? g.toNonIndexed() : g)));
  // đèn báo hàng không trên đỉnh 4 cột
  const beacons = new THREE.InstancedMesh(new THREE.SphereGeometry(0.55, 10, 8), M.beacon, 4);
  const m = new THREE.Matrix4(); let k = 0;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) beacons.setMatrixAt(k++, m.makeTranslation(sx * TP.towerX, TP.towerTop + 2.5, sz * TP.cablePlaneZ));
  bridge.group.add(beacons);
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CONFIG } from '../../config';
import { lerp } from '../../common/math';
import { segmentMatrix, UP } from '../../common/geometry';
import { TP, tpRoadY, tpCableY, tpHangerStations } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [cables] cáp chủ, 114 hanger và kẹp cáp */
export function tpBuildCables(bridge: ThuanPhuocBridge) {
  const M = bridge.mats, tubes = [], Zc = TP.cablePlaneZ;
  // 3 đoạn mỗi mặt phẳng: nhịp biên Tây, nhịp chính, nhịp biên Đông (gãy góc tại yên ngựa)
  const spans = [[-TP.cableAnchorX, -TP.towerX], [-TP.towerX, TP.towerX], [TP.towerX, TP.cableAnchorX]];
  for (const sz of [-1, 1]) for (const [a, b] of spans) {
    const n = Math.max(12, Math.round((b - a) / 2)), pts = [];
    for (let i = 0; i <= n; i++) { const x = lerp(a, b, i / n); pts.push(new THREE.Vector3(x, tpCableY(x), sz * Zc)); }
    tubes.push(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), n * 2, TP.cableRadius, 10, false));
  }
  const cables = new THREE.Mesh(mergeGeometries(tubes), M.cable); cables.name = 'tp-main-cables'; cables.castShadow = true;
  bridge.group.add(cables);

  // Hanger (114) và kẹp cáp tại mỗi hanger
  const st = tpHangerStations(), hangers = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 6, CONFIG.weather.wind.cableSegs), M.hanger, st.length * 2);
  const bands = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 12), M.steel, st.length * 2);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), tng = new THREE.Vector3(), sc = new THREE.Vector3();
  let k = 0;
  for (const { x, special } of st) for (const sz of [-1, 1]) {
    const top = new THREE.Vector3(x, tpCableY(x) - TP.cableRadius, sz * Zc);
    const bot = new THREE.Vector3(x, tpRoadY(x) - 0.9, sz * (TP.girderTip + 0.05));
    hangers.setMatrixAt(k, segmentMatrix(top, bot, special ? TP.hangerRSpecial : TP.hangerR, m));
    tng.set(1, tpCableY(x + 0.5) - tpCableY(x - 0.5), 0).normalize();
    q.setFromUnitVectors(UP, tng);
    bands.setMatrixAt(k, m.compose(new THREE.Vector3(x, tpCableY(x), sz * Zc), q, sc.set(TP.bandRadius, 1.2, TP.bandRadius)));
    k++;
  }
  bridge.group.add(hangers);
  bridge.details.add(bands);
  bridge.stats.hangers = k;
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { prepColored, extrudeAlongX, boxAt, loftOct, fillBlock } from '../../common/geometry';
import { TP, tpRoadY } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [approaches] cầu dẫn BTCT, khối neo cáp, mố, đường đắp, trụ cầu dẫn */
export function tpBuildApproaches(bridge: ThuanPhuocBridge) {
  const A = TP.anchorX, E = TP.endX, R = TP.embankment, hw = TP.deckWidth / 2, dd = TP.approachDepth;
  // Dầm hộp BTCT dự ứng lực liên tục: bản cánh rộng, sườn vát
  const sec = [[-hw, 0], [hw, 0], [hw, -0.3], [5.2, -0.6], [4.4, -dd], [-4.4, -dd], [-5.2, -0.6], [-hw, -0.3]];
  for (const s of [-1, 1]) {
    const [a, b] = s > 0 ? [A, E] : [-E, -A];
    bridge.concreteParts.push(prepColored(extrudeAlongX(sec, a, b, 160, tpRoadY)));
    // khối neo cáp: thân neo dưới mặt cầu + buồng neo hai bên
    const top = TP.roadAnchorY - TP.girderDepth - 0.5;
    bridge.concreteParts.push(prepColored(boxAt(48, top + 1, 32, s * (A + 16), (top - 1) / 2, 0, 4)));
    for (const sz of [-1, 1]) bridge.concreteParts.push(prepColored(loftOct([24, 5], [22, 4.4], top, TP.anchorCableY + 1.6,
      [s * (A + 14), sz * 12], [s * (A + 14), sz * 12], 0.4)));
    // mố cầu + tường chắn đường đắp
    bridge.concreteParts.push(prepColored(boxAt(6, tpRoadY(E) - CONFIG.landY + 1, TP.deckWidth + 2, s * E, (tpRoadY(E) + CONFIG.landY - 1) / 2 - 0.3, 0)));
    const [f0, f1] = s > 0 ? [E, E + R] : [-E - R, -E];
    bridge.concreteParts.push(prepColored(fillBlock(f0, f1, TP.deckWidth, 0, CONFIG.landY - 0.5, (x) => tpRoadY(x) - 0.05, 40), () => 0.82));
  }
  // Trụ cầu dẫn (InstancedMesh): thân trụ ô-van + xà mũ
  const xs = [];
  for (const s of [-1, 1]) for (let i = 1; i < TP.approachSpans; i++) xs.push(s * (A + i * TP.approachSpanLen));
  const colGeo = prepColored(new THREE.CylinderGeometry(1, 1, 1, 20).translate(0, 0.5, 0));
  const capGeo = prepColored(new THREE.BoxGeometry(1, 1, 1));
  const cols = new THREE.InstancedMesh(colGeo, bridge.mats.concrete, xs.length);
  const caps = new THREE.InstancedMesh(capGeo, bridge.mats.concrete, xs.length);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), sc = new THREE.Vector3();
  xs.forEach((x, i) => {
    const capTop = tpRoadY(x) - dd, capH = 1.6, h = capTop - capH - (CONFIG.landY - 1);
    cols.setMatrixAt(i, m.compose(v.set(x, CONFIG.landY - 1, 0), q, sc.set(1.4, h, 2.6)));
    caps.setMatrixAt(i, m.compose(v.set(x, capTop - capH / 2, 0), q, sc.set(3.0, capH, 11)));
  });
  cols.castShadow = caps.castShadow = true; cols.receiveShadow = caps.receiveShadow = true;
  bridge.group.add(cols, caps);
}

